/**
 * Adds a `travelAdvisory` block to every journeyGuides.ts entry that was
 * generated by generate-journey-guides.mjs (everything except the 11
 * original hand-written guides, which already have one) — so "Travel
 * Advisory" is a consistent tab across every destination, matching the
 * Agra reference. Same grounding rules as the rest of the generator: no
 * fabricated per-place claims — alerts/dos/donts/health/culture/money
 * tips are genuinely reliable, broadly-true India travel guidance, and
 * the season-specific fields reuse the same state climate template
 * already used for weatherSeasons, so "best time to visit" stays
 * consistent with what the "What to Pack" tab says for the same place.
 * `updatedFrom` is honest about not being a verified official source.
 */
import { readFileSync, writeFileSync } from "fs";

const { getStateTemplate, NATIONAL_UPI } = await import("../src/data/stateJourneyTemplates.ts");

const ORIGINAL_IDS = new Set(["agra", "jaipur", "kerala", "goa", "ladakh", "varanasi", "andaman", "udaipur", "rishikesh", "darjeeling", "khajuraho"]);

function esc(s) {
  return String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function buildAdvisory(destination) {
  const t = getStateTemplate(destination.state);
  const [first, ...rest] = t.weatherSeasons;

  const alerts = [
    { level: "info", icon: "🌦️", title: `${first.season} is generally the most comfortable time to visit`, detail: first.warning },
    ...rest.map((s) => ({
      level: s.season.toLowerCase().includes("monsoon") ? "caution" : "info",
      icon: s.season.toLowerCase().includes("monsoon") ? "⚠️" : "🌦️",
      title: `Planning around ${s.season.toLowerCase()} (${s.months})`,
      detail: s.warning,
    })),
  ];

  return {
    updatedFrom: "General travel guidance (not sourced from an official state tourism advisory)",
    bestTimeToVisit: `${first.months} (${first.season})`,
    peakSeason: first.months,
    offSeason: rest.length ? rest.map((s) => s.months).join(" and ") : "Check locally — conditions vary through the year",
    alerts,
    dos: [
      "Dress modestly at religious sites — cover shoulders and knees",
      "Carry a government-issued photo ID at all times",
      "Stay hydrated and carry water, especially in hot weather",
      "Use registered taxis, prepaid counters, or well-known app cabs",
      "Keep small-denomination cash on hand for local vendors",
    ],
    donts: [
      "Don't drink tap water — stick to sealed bottled or filtered water",
      "Don't accept unsolicited help from strangers near tourist sites — politely decline and walk on",
      "Don't photograph people, especially at religious sites, without asking first",
      "Don't flash cash or valuables in crowded areas",
    ],
    emergencyContacts: [
      { label: "All-in-one Emergency", number: "112", icon: "🚨" },
      { label: "Ambulance", number: "102", icon: "🚑" },
      { label: "Police", number: "100", icon: "👮" },
      { label: "Fire", number: "101", icon: "🚒" },
    ],
    healthTips: [
      "Carry a basic first-aid kit and any personal medication you need",
      "Use sunscreen and stay hydrated, especially in hot or high-altitude areas",
      "Travel/health insurance is strongly recommended for any India trip",
    ],
    culturalNotes: [
      t.language,
      "Remove footwear before entering temples and most homes",
      "A namaste (palms together, slight bow) is a warm, universally understood greeting",
    ],
    moneyTips: [
      NATIONAL_UPI,
      "ATMs are available in nearby towns — withdraw cash in advance for more remote stops",
      "Bargaining is normal and expected at local markets, less so in fixed-price or branded stores",
    ],
  };
}

function advisoryToTs(a) {
  const alertsTs = a.alerts.map((al) => `        { level: "${al.level}", icon: "${esc(al.icon)}", title: "${esc(al.title)}", detail: "${esc(al.detail)}" },`).join("\n");
  const arr = (xs) => xs.map((x) => `"${esc(x)}"`).join(", ");
  const contactsTs = a.emergencyContacts.map((ec) => `        { label: "${esc(ec.label)}", number: "${esc(ec.number)}", icon: "${esc(ec.icon)}" },`).join("\n");

  return `    travelAdvisory: {
      updatedFrom: "${esc(a.updatedFrom)}",
      bestTimeToVisit: "${esc(a.bestTimeToVisit)}",
      peakSeason: "${esc(a.peakSeason)}",
      offSeason: "${esc(a.offSeason)}",
      alerts: [
${alertsTs}
      ],
      dos: [${arr(a.dos)}],
      donts: [${arr(a.donts)}],
      emergencyContacts: [
${contactsTs}
      ],
      healthTips: [${arr(a.healthTips)}],
      culturalNotes: [${arr(a.culturalNotes)}],
      moneyTips: [${arr(a.moneyTips)}],
    },`;
}

// --- main ---
const destContent = readFileSync("src/data/destinations.ts", "utf8");
const destStartIdx = destContent.indexOf("const DESTINATIONS_PART_1");
const destBody = destContent.slice(destStartIdx);
const idMarker = /^    id: "([^"]+)",/gm;
const indices = [];
let m;
while ((m = idMarker.exec(destBody))) indices.push({ idx: m.index, id: m[1] });

const destinationById = {};
for (let i = 0; i < indices.length; i++) {
  const start = indices[i].idx;
  const end = i + 1 < indices.length ? indices[i + 1].idx : destBody.length;
  const chunk = destBody.slice(start, end);
  const nameMatch = chunk.match(/name: "((?:[^"\\]|\\.)*)"/);
  const stateMatch = chunk.match(/state: "((?:[^"\\]|\\.)*)"/);
  if (nameMatch && stateMatch) destinationById[indices[i].id] = { id: indices[i].id, name: nameMatch[1], state: stateMatch[1] };
}

let guidesContent = readFileSync("src/data/journeyGuides.ts", "utf8");

const destIdRe = /destId: "([^"]+)",/g;
const guideStarts = [];
let gm;
while ((gm = destIdRe.exec(guidesContent))) guideStarts.push({ idx: gm.index, id: gm[1] });

let patched = 0;
let skippedOriginal = 0;
let skippedNoDest = 0;
let skippedAlreadyHas = 0;
// Process from the END backwards so earlier insertions don't shift the
// offsets of guides we haven't processed yet.
for (let i = guideStarts.length - 1; i >= 0; i--) {
  const { idx, id } = guideStarts[i];
  if (ORIGINAL_IDS.has(id)) { skippedOriginal++; continue; }
  const destination = destinationById[id];
  if (!destination) { skippedNoDest++; continue; }

  const blockEnd = i + 1 < guideStarts.length ? guideStarts[i + 1].idx : guidesContent.length;
  const block = guidesContent.slice(idx, blockEnd);
  // Idempotency guard — without this, re-running the script on a file
  // that already has travelAdvisory entries (e.g. after adding one new
  // destination) silently double-inserts into every guide that already
  // has one. Found this the hard way.
  if (/\n    travelAdvisory: \{/.test(block)) { skippedAlreadyHas++; continue; }
  const ftdMatch = block.match(/\n    firstThingsToDo: \[\],\n/);
  if (!ftdMatch) { console.error(`WARNING: couldn't find insertion point for ${id}`); continue; }

  const insertAt = idx + ftdMatch.index + ftdMatch[0].length;
  const advisoryTs = advisoryToTs(buildAdvisory(destination)) + "\n";
  guidesContent = guidesContent.slice(0, insertAt) + advisoryTs + guidesContent.slice(insertAt);
  patched++;
}

console.error(`patched: ${patched}, skipped (original 11): ${skippedOriginal}, skipped (already has one): ${skippedAlreadyHas}, skipped (no matching destination): ${skippedNoDest}`);
writeFileSync("src/data/journeyGuides.ts", guidesContent);
console.error("wrote journeyGuides.ts");
